"""Replay-dedupe cache for receipt verification commands (issue #164).

The SubagentStop hook (synaptory-verify-receipt.sh → verification_runner.py)
re-runs every receipt's `verification_commands`. In a measured sprint the
same command at the same repo tree-state was replayed 50+ times. This module
caches replay results keyed on (command, tree state) so identical replays
can be served from disk instead of re-executed.

Cache invalidation is structural, not heuristic: the key embeds a digest of
`HEAD` + `git status --porcelain` + `git diff`, so *any* tree change (a new
commit, a dirty file, a staged hunk) changes the tree-state digest and every
prior entry misses naturally. Conservative by design.

Store: `.synaptory/.orchestrator/verification-cache.json` under the project
dir. Writes are atomic (tmp file + os.replace). A corrupt or missing cache
file degrades to an empty cache — this module must never crash the hook.

Results returned by `lookup()` are exactly what the caller stored; marking a
result as "served from cache" is the CALLER's responsibility.

Public API:
    tree_state(project_dir) -> str | None
    lookup(project_dir, command) -> dict | None
    store(project_dir, command, result) -> None
    prune(project_dir, max_age_days=14, max_entries=500) -> None
    clear(project_dir) -> None
"""

# NFR-PLUGIN-2: Python 3.9+. Annotations below use PEP 604 unions
# (`X | None`); the future-import defers evaluation so 3.9 doesn't
# choke at module-load time.
from __future__ import annotations

import hashlib
import json
import os
import subprocess
import tempfile
from datetime import datetime, timedelta, timezone
from typing import Any

GIT_TIMEOUT = 10  # seconds per git call
DEFAULT_MAX_AGE_DAYS = 14
DEFAULT_MAX_ENTRIES = 500

_CACHE_RELPATH = os.path.join(".synaptory", ".orchestrator", "verification-cache.json")

# The .synaptory/ state dir must not count as tree state: the cache file
# itself lives there (storing an entry would otherwise invalidate it), and
# orchestrator state files churn constantly without affecting what
# verification commands would observe.
_TREE_PATHSPEC = ("--", ":(exclude).synaptory")


# ─── Paths ────────────────────────────────────────────────────────────────────


def cache_path(project_dir: str) -> str:
    """Absolute path of the cache file for a project."""
    return os.path.join(project_dir, _CACHE_RELPATH)


# ─── Tree state ───────────────────────────────────────────────────────────────


def _git(project_dir: str, *args: str) -> str | None:
    """Run a git command; return stdout, or None on any failure.

    Failures (git missing, not a repo, timeout) disable caching for the
    call — never raise.
    """
    try:
        proc = subprocess.run(
            ["git", "-C", project_dir, *args],
            shell=False,
            capture_output=True,
            text=True,
            timeout=GIT_TIMEOUT,
        )
    except (OSError, subprocess.TimeoutExpired, subprocess.SubprocessError):
        return None
    if proc.returncode != 0:
        return None
    return proc.stdout


def tree_state(project_dir: str) -> str | None:
    """Digest of the repo's current tree state, or None if git is unusable.

    Combines HEAD, `status --porcelain`, and `diff` into a single sha256 hex
    digest. Any commit, stage, or working-tree edit changes the digest.
    None means caching is disabled (not a git repo, git missing, etc.).
    """
    head = _git(project_dir, "rev-parse", "HEAD")
    status = _git(project_dir, "status", "--porcelain", *_TREE_PATHSPEC)
    diff = _git(project_dir, "diff", *_TREE_PATHSPEC)
    if head is None or status is None or diff is None:
        return None
    combined = "\n".join(
        [
            head.strip(),
            hashlib.sha256(status.encode("utf-8")).hexdigest(),
            hashlib.sha256(diff.encode("utf-8")).hexdigest(),
        ]
    )
    return hashlib.sha256(combined.encode("utf-8")).hexdigest()


# ─── Cache file I/O ───────────────────────────────────────────────────────────


def _load(project_dir: str) -> dict[str, Any]:
    """Load the cache file. Corrupt/missing → empty cache, never crash."""
    try:
        with open(cache_path(project_dir), "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError, UnicodeDecodeError):
        return {"entries": {}}
    if not isinstance(data, dict) or not isinstance(data.get("entries"), dict):
        return {"entries": {}}
    return data


def _save(project_dir: str, cache: dict[str, Any]) -> None:
    """Atomic write: tmp file in the same dir + os.replace. Best-effort."""
    path = cache_path(project_dir)
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(
            prefix=".verification-cache-", suffix=".tmp", dir=os.path.dirname(path)
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(cache, f, indent=2, sort_keys=True)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise
    except OSError:
        # Read-only FS or similar — caching is an optimisation, not a
        # correctness requirement. Silently degrade.
        pass


def _command_key(command: str) -> str:
    return hashlib.sha256(command.encode("utf-8")).hexdigest()


# ─── Public API ───────────────────────────────────────────────────────────────


def lookup(project_dir: str, command: str) -> dict | None:
    """Return the stored result for `command` at the CURRENT tree state.

    None on miss, tree-state mismatch, or when caching is disabled
    (non-git dir). The returned dict is exactly what `store()` persisted;
    the caller is responsible for marking it as cache-served.
    """
    state = tree_state(project_dir)
    if state is None:
        return None
    entry = _load(project_dir)["entries"].get(_command_key(command))
    if not isinstance(entry, dict):
        return None
    if entry.get("tree_state") != state:
        return None
    result = entry.get("result")
    return result if isinstance(result, dict) else None


def store(project_dir: str, command: str, result: dict) -> None:
    """Persist a replay result keyed on (command, current tree state).

    No-op when caching is disabled (non-git dir). Prunes stale/overflow
    entries on every store.
    """
    state = tree_state(project_dir)
    if state is None:
        return
    cache = _load(project_dir)
    cache["entries"][_command_key(command)] = {
        "command": command,
        "tree_state": state,
        "result": result,
        "stored_at": datetime.now(timezone.utc).isoformat(),
    }
    _prune_entries(cache, DEFAULT_MAX_AGE_DAYS, DEFAULT_MAX_ENTRIES)
    _save(project_dir, cache)


def prune(
    project_dir: str,
    max_age_days: int = DEFAULT_MAX_AGE_DAYS,
    max_entries: int = DEFAULT_MAX_ENTRIES,
) -> None:
    """Drop entries older than `max_age_days`, then oldest beyond `max_entries`."""
    path = cache_path(project_dir)
    if not os.path.exists(path):
        return
    cache = _load(project_dir)
    _prune_entries(cache, max_age_days, max_entries)
    _save(project_dir, cache)


def clear(project_dir: str) -> None:
    """Delete the cache file entirely (sprint-boundary reset)."""
    try:
        os.unlink(cache_path(project_dir))
    except OSError:
        pass


# ─── Prune internals ──────────────────────────────────────────────────────────


def _stored_at(entry: Any) -> datetime:
    """Parse an entry's stored_at; unparseable → epoch (pruned first)."""
    epoch = datetime.fromtimestamp(0, tz=timezone.utc)
    if not isinstance(entry, dict):
        return epoch
    raw = entry.get("stored_at")
    if not isinstance(raw, str):
        return epoch
    try:
        ts = datetime.fromisoformat(raw)
    except ValueError:
        return epoch
    if ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    return ts


def _prune_entries(cache: dict[str, Any], max_age_days: int, max_entries: int) -> None:
    """In-place prune: drop stale entries, then oldest beyond the cap."""
    entries = cache.get("entries")
    if not isinstance(entries, dict):
        cache["entries"] = {}
        return
    cutoff = datetime.now(timezone.utc) - timedelta(days=max_age_days)
    fresh = {k: v for k, v in entries.items() if _stored_at(v) >= cutoff}
    if len(fresh) > max_entries:
        newest_first = sorted(fresh.items(), key=lambda kv: _stored_at(kv[1]), reverse=True)
        fresh = dict(newest_first[:max_entries])
    cache["entries"] = fresh
